import type { Metadata } from "next";
import { DM_Sans, DM_Mono } from "next/font/google";
import { ThemeProvider } from "@/components/theme-provider";
import "./globals.css";

const dmSans = DM_Sans({
  variable: "--font-sans",
  subsets: ["latin"],
  weight: ["400", "500", "700"],
});

const dmMono = DM_Mono({
  variable: "--font-mono",
  subsets: ["latin"],
  weight: ["400"],
});

export const metadata: Metadata = {
  title: "Claude Code for Designers",
  description:
    "A practical guide to using Claude Code as a designer. Tips, workflows, and exercises to get started.",
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    <html lang="en" suppressHydrationWarning>
      <body
        className={`${dmSans.variable} ${dmMono.variable} font-sans antialiased`}
      >
        <ThemeProvider
          attribute="class"
          defaultTheme="system"
          enableSystem
          disableTransitionOnChange={false}
        >
          {children}
        </ThemeProvider>
      </body>
    </html>
  );
}

"use client";

import { useTheme } from "next-themes";
import { useEffect, useState } from "react";
import { Button } from "@/components/ui/button";

export function ThemeToggle() {
  const { theme, setTheme } = useTheme();
  const [mounted, setMounted] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  if (!mounted) {
    return (
      <Button variant="ghost" size="icon" className="h-9 w-9">
        <span className="sr-only">Toggle theme</span>
      </Button>
    );
  }

  return (
    <Button
      variant="ghost"
      size="icon"
      className="h-9 w-9"
      onClick={() => setTheme(theme === "dark" ? "light" : "dark")}
    >
      {theme === "dark" ? (
        <svg
          xmlns="http://www.w3.org/2000/svg"
          width="18"
          height="18"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
        >
          <circle cx="12" cy="12" r="4" />
          <path d="M12 2v2" />
          <path d="M12 20v2" />
          <path d="m4.93 4.93 1.41 1.41" />
          <path d="m17.66 17.66 1.41 1.41" />
          <path d="M2 12h2" />
          <path d="M20 12h2" />
          <path d="m6.34 17.66-1.41 1.41" />
          <path d="m19.07 4.93-1.41 1.41" />
        </svg>
      ) : (
        <svg
          xmlns="http://www.w3.org/2000/svg"
          width="18"
          height="18"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
        >
          <path d="M12 3a6 6 0 0 0 9 9 9 9 0 1 1-9-9Z" />
        </svg>
      )}
      <span className="sr-only">Toggle theme</span>
    </Button>
  );
}

import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

"use client";

import { useState } from "react";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { ThemeToggle } from "@/components/theme-toggle";
import { GuideContent } from "@/components/guide-content";
import { PracticeContent } from "@/components/practice-content";
import { AboutContent } from "@/components/about-content";

export default function Home() {
  const [view, setView] = useState<"tabs" | "about">("tabs");

  return (
    <div className="min-h-screen bg-background text-foreground transition-colors duration-300">
      <Tabs defaultValue="guide" className="w-full">
        {/* Navbar */}
        <header className="sticky top-0 z-50 w-full border-b border-border/50 bg-background/80 backdrop-blur-md">
          <div className="mx-auto flex h-14 max-w-5xl items-center justify-between px-6">
            <button
              onClick={() => setView("tabs")}
              className="text-sm font-bold tracking-tight hover:opacity-70 transition-opacity cursor-pointer"
            >
              cc for designers
            </button>
            {view === "tabs" ? (
              <TabsList className="h-9 bg-muted/50">
                <TabsTrigger value="guide" className="text-sm px-4">
                  Guide
                </TabsTrigger>
                <TabsTrigger value="practice" className="text-sm px-4">
                  Practice
                </TabsTrigger>
              </TabsList>
            ) : (
              <span className="text-sm text-muted-foreground">About</span>
            )}
            <div className="flex items-center gap-3">
              <button
                onClick={() => setView(view === "about" ? "tabs" : "about")}
                className={`text-sm transition-colors cursor-pointer ${
                  view === "about"
                    ? "text-foreground font-medium"
                    : "text-muted-foreground hover:text-foreground"
                }`}
              >
                About
              </button>
              <ThemeToggle />
            </div>
          </div>
        </header>

        {/* Content */}
        <main className="mx-auto max-w-[720px] px-6 py-12">
          {view === "about" ? (
            <AboutContent />
          ) : (
            <>
              <TabsContent value="guide" className="mt-0">
                <GuideContent />
              </TabsContent>
              <TabsContent value="practice" className="mt-0">
                <PracticeContent />
              </TabsContent>
            </>
          )}
        </main>
      </Tabs>

      {/* Footer */}
      <footer className="border-t border-border/50 py-8 text-center text-sm text-muted-foreground">
        made by{" "}
        <a
          href="https://pablostanley.substack.com/"
          target="_blank"
          rel="noopener noreferrer"
          className="underline underline-offset-4 hover:text-foreground transition-colors"
        >
          pablo stanley
        </a>
        {" "}&mdash; shippit
      </footer>
    </div>
  );
}

"use client";

import { useState } from "react";
import { ChevronDown } from "lucide-react";

export function PracticeContent() {
  const [open, setOpen] = useState(false);

  return (
    <div className="space-y-8 pb-16">
      <header className="mb-12">
        <h1 className="text-4xl font-bold tracking-tight mb-4">Practice</h1>
        <p className="text-lg text-muted-foreground leading-relaxed">
          Three exercises to put the guide into practice. Each one builds on
          concepts from the guide. Follow the setup steps below, then pick an
          exercise.
        </p>
      </header>

      {/* Setup Steps — Collapsible */}
      <div className="rounded-xl border border-border/50 bg-card overflow-hidden">
        <button
          onClick={() => setOpen(!open)}
          className="flex w-full items-center justify-between p-6 text-left hover:bg-muted/30 transition-colors cursor-pointer"
        >
          <div>
            <h2 className="text-xl font-bold tracking-tight">
              Before you start
            </h2>
            <p className="text-sm text-muted-foreground mt-1">
              Quick setup guide before prompting
            </p>
          </div>
          <ChevronDown
            className={`h-5 w-5 shrink-0 text-muted-foreground transition-transform duration-200 ${open ? "rotate-180" : ""}`}
          />
        </button>
        {open && (
          <div className="px-6 pb-6 pt-0">
            <hr className="border-border/50 mb-6" />
            <ol className="space-y-6">
              <SetupStep number={1}>
                <p className="text-base text-muted-foreground leading-relaxed">
                  <strong>Open your terminal.</strong> On Mac, search for
                  Terminal in Spotlight, or use{" "}
                  <a
                    href="https://ghostty.org"
                    target="_blank"
                    rel="noopener noreferrer"
                    className="underline underline-offset-4 hover:text-foreground transition-colors"
                  >
                    Ghostty
                  </a>{" "}
                  if u want something nicer.
                </p>
              </SetupStep>
              <SetupStep number={2}>
                <p className="text-base text-muted-foreground leading-relaxed">
                  <strong>Create a folder and cd into it.</strong> This is where
                  your project will live.
                </p>
                <CodeSnippet code="mkdir my-project && cd my-project" />
              </SetupStep>
              <SetupStep number={3}>
                <p className="text-base text-muted-foreground leading-relaxed">
                  <strong>Start Claude with skip permissions.</strong> So u
                  don&apos;t have to say &ldquo;yes&rdquo; to every action.
                </p>
                <CodeSnippet code="claude --dangerously-skip-permissions" />
              </SetupStep>
              <SetupStep number={4}>
                <p className="text-base text-muted-foreground leading-relaxed">
                  <strong>Write your prompt.</strong> Be specific. Paste one of
                  the exercise prompts below, or write your own. Hit enter and
                  watch Claude build it.
                </p>
              </SetupStep>
              <SetupStep number={5}>
                <p className="text-base text-muted-foreground leading-relaxed">
                  <strong>Connect GitHub &amp; deploy.</strong> Once you&apos;re
                  happy with it, ask Claude to set up git and push to GitHub.
                  Then deploy.
                </p>
                <CodeSnippet
                  code={`# just tell Claude:
"init git, create a GitHub repo called my-project, push everything"

# then:
"deploy this to Vercel"`}
                />
                <p className="text-sm text-muted-foreground/70 mt-3">
                  Make sure u have the{" "}
                  <a
                    href="https://cli.github.com"
                    target="_blank"
                    rel="noopener noreferrer"
                    className="underline underline-offset-4 hover:text-foreground transition-colors"
                  >
                    GitHub CLI
                  </a>{" "}
                  installed (
                  <code className="inline-code">brew install gh</code>) and
                  logged in (
                  <code className="inline-code">gh auth login</code>). Claude
                  uses it to create repos and push for u. For deploying, install
                  the{" "}
                  <a
                    href="https://vercel.com"
                    target="_blank"
                    rel="noopener noreferrer"
                    className="underline underline-offset-4 hover:text-foreground transition-colors"
                  >
                    Vercel CLI
                  </a>{" "}
                  (<code className="inline-code">npm i -g vercel</code>) or add
                  the Vercel MCP.
                </p>
              </SetupStep>
            </ol>
          </div>
        )}
      </div>

      <hr className="border-border/50 my-12" />

      <h2 className="text-2xl font-bold tracking-tight mb-2">Exercises</h2>
      <p className="text-lg text-muted-foreground leading-relaxed mb-8">
        Pick one. Copy the prompt. Paste it into Claude. Then iterate from
        there.
      </p>

      {/* Exercise 1 */}
      <ExerciseCard
        number={1}
        title="Personal Landing Page"
        description="Build a personal portfolio landing page with a hero section, about section, and project grid. Start from scratch in Claude Code."
        prompt={`create a personal landing page with a full-height hero with my name centered, an about section with two columns (photo left, text right), and a 3-column project grid with hover effects. Use Inter font, clean minimal design, dark background.`}
        concepts={["Be Specific", "Plan Mode", "CLAUDE.md"]}
      />

      {/* Exercise 2 */}
      <ExerciseCard
        number={2}
        title="Analytics Dashboard"
        description="Build a simple analytics dashboard with charts, stat cards, and a sidebar nav."
        prompt={`build an analytics dashboard with a left sidebar nav, top stat cards showing revenue/users/growth with sparklines, a main area chart for monthly data, and a recent activity table. Use shadcn components, clean layout, responsive.`}
        concepts={["Subagents", "Skills", "Browser Agent"]}
      />

      {/* Exercise 3 */}
      <ExerciseCard
        number={3}
        title="Design System Starter"
        description="Create a design system page that documents your own tokens, components, and patterns."
        prompt={`create a design system documentation page with sections for: color palette (show swatches with hex values), typography scale (show each heading and body size), spacing scale (visual blocks), and a component showcase with buttons, inputs, cards in all their variants. Make it responsive and add a sidebar nav to jump between sections.`}
        concepts={["CLAUDE.md Rules", "Custom Skills", "Fix"]}
      />
    </div>
  );
}

function SetupStep({
  number,
  children,
}: {
  number: number;
  children: React.ReactNode;
}) {
  return (
    <li className="flex gap-4 min-w-0">
      <span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-muted text-xs font-bold text-muted-foreground">
        {number}
      </span>
      <div className="min-w-0 flex-1">{children}</div>
    </li>
  );
}

function CodeSnippet({ code }: { code: string }) {
  return (
    <div className="rounded-lg bg-[#1a1a1a] border border-white/5 overflow-x-auto mt-3">
      <pre className="p-4 text-sm leading-relaxed">
        <code className="text-neutral-300 font-mono whitespace-pre-wrap break-words">
          {code}
        </code>
      </pre>
    </div>
  );
}

function ExerciseCard({
  number,
  title,
  description,
  prompt,
  concepts,
}: {
  number: number;
  title: string;
  description: string;
  prompt: string;
  concepts: string[];
}) {
  return (
    <div className="rounded-xl border border-border/50 bg-card p-8 transition-colors overflow-hidden">
      <div className="flex items-center gap-3 mb-4">
        <span className="flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-muted text-sm font-bold text-muted-foreground">
          {number}
        </span>
        <h2 className="text-xl font-bold tracking-tight">{title}</h2>
      </div>
      <p className="text-lg text-muted-foreground leading-relaxed mb-6">
        {description}
      </p>
      <div className="rounded-lg bg-[#1a1a1a] border border-white/5 overflow-x-auto mb-6">
        <div className="px-4 pt-3 text-xs text-neutral-500 font-mono">
          prompt
        </div>
        <pre className="p-4 pt-2 text-sm leading-relaxed">
          <code className="text-neutral-300 font-mono whitespace-pre-wrap break-words">
            {prompt}
          </code>
        </pre>
      </div>
      <div className="flex flex-wrap gap-2">
        {concepts.map((concept) => (
          <span
            key={concept}
            className="inline-flex items-center rounded-md border border-border/50 bg-muted/50 px-3 py-1 text-xs font-medium text-muted-foreground"
          >
            {concept}
          </span>
        ))}
      </div>
    </div>
  );
}

